// Find the time inside window when nobody in calendars is busy.
//
// A time is a string "HH:MM" on a 24-hour clock: exactly two digits, a colon and two
// digits, with 00 <= HH <= 23 and 00 <= MM <= 59; "24:00" is also valid and means the
// end of the day. An interval (start, end) is half-open: from start up to but not
// including end. calendars holds one list of busy intervals per person. Busy intervals
// may be unsorted, overlap, touch each other and extend outside the window; one with
// start == end is busy for no time at all.
//
// Return Some of the maximal free intervals inside window (times when no person is busy)
// whose length is at least min_minutes, sorted by start, each as a (start, end) pair of
// times in the same "HH:MM" format ("24:00" for the end of the day).
// Return None if any time (busy or window) is malformed, any busy interval has
// start > end, the window does not have start < end, or min_minutes < 1.
// Examples:
//   find_free_slots([[("09:00", "10:30")], [("12:00", "13:00"), ("10:00", "11:00")]], ("08:00", "14:00"), 30)
//     == Some([("08:00", "09:00"), ("11:00", "12:00"), ("13:00", "14:00")])
//   find_free_slots([[("08:30", "09:10")]], ("09:00", "09:20"), 15) == Some([])
fn find_free_slots(calendars: List[List[(Str, Str)]], window: (Str, Str), min_minutes: Int) -> Option[List[(Str, Str)]] {
  let lo = parse_time(window.0)?;
  let hi = parse_time(window.1)?;
  if lo >= hi || min_minutes < 1 {
    return None;
  }
  let mut busy: List[(Int, Int)] = [];
  for person in calendars {
    for iv in person {
      let a = parse_time(iv.0)?;
      let b = parse_time(iv.1)?;
      if a > b {
        return None;
      }
      let ca = max(a, lo);
      let cb = min(b, hi);
      if ca < cb {
        busy = push(busy, (ca, cb));
      }
    }
  }
  let sorted = sort_by(busy, |iv| iv.0);
  let mut free: List[(Str, Str)] = [];
  let mut cur = lo;
  for iv in sorted {
    if iv.0 - cur >= min_minutes {
      free = push(free, (format_time(cur), format_time(iv.0)));
    }
    cur = max(cur, iv.1);
  }
  if hi - cur >= min_minutes {
    free = push(free, (format_time(cur), format_time(hi)));
  }
  Some(free)
}

fn parse_time(t: Str) -> Option[Int] {
  let cs = chars(t);
  if len(cs) != 5 || cs[2] != ":" {
    return None;
  }
  for i in [0, 1, 3, 4] {
    if !is_digit(cs[i]) {
      return None;
    }
  }
  let h = parse_int(substr(t, 0, 2))?;
  let m = parse_int(substr(t, 3, 5))?;
  if m > 59 || h > 24 || (h == 24 && m != 0) {
    return None;
  }
  Some(h * 60 + m)
}

fn format_time(x: Int) -> Str {
  pad2(x / 60) ++ ":" ++ pad2(x % 60)
}

fn pad2(n: Int) -> Str {
  if n < 10 { "0" ++ show(n) } else { show(n) }
}
